mapper.select:
SELECT id, user_id AS userId, target_type AS targetType, target_id AS targetId,
       view_count AS viewCount, last_viewed_at AS lastViewedAt,
       deleted, created_at AS createdAt, updated_at AS updatedAt
FROM user_reading_history
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
LIMIT 1

mapper.update:
UPDATE user_reading_history
SET deleted = 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND deleted = 0
